window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[91]={"id":"091","numero":91,"titre":"Déficit neurologique récent","objectifs":[{"id":"91-1","rang":"A","rubrique":"Définition","titre":"Définir la notion de déficit neurologique focal vs trouble cérébral diffus","contenu":"<table >\n        <thead><tr><th>Terme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Déficit neurologique</strong></span></td>\n            <td><span class=\"kw-def\">Dysfonction</span> temporaire (<span class=\"kw-def\">déficit transitoire</span>) ou lésionnelle (<span class=\"kw-def\">déficit permanent</span>) d'une région du système nerveux</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-chiffre\"><strong>Récent</strong></span></td>\n            <td>Apparu depuis <span class=\"kw-chiffre\"><strong>moins d'1 mois</strong></span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Déficit focal</strong></span></td>\n            <td>Dysfonction <span class=\"kw-def\">localisée</span> à une région précise du système nerveux — signe d'une <span class=\"kw-clinique\">lésion</span> ou irritation focale</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Souffrance cérébrale diffuse</strong></span></td>\n            <td><span class=\"kw-alerte\">Perte de connaissance</span>, <span class=\"kw-clinique\">coma</span>, <span class=\"kw-alerte\">syndrome confusionnel</span> — atteinte globale du cerveau, à distinguer du déficit focal</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Ne pas confondre un <span class=\"kw-alerte\">déficit neurologique focal récent</span> avec un <span class=\"kw-alerte\">trouble de conscience global</span> (<span class=\"kw-clinique\">coma</span>, <span class=\"kw-clinique\">confusion</span>) ou une <span class=\"kw-clinique\">syncope</span> — ces derniers relèvent d'une autre démarche diagnostique.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 343 — Etat confusionnel - trouble de conscience</em></p>","frequence":0},{"id":"91-2","rang":"A","rubrique":"Diagnostic positif","titre":"Reconnaître un déficit récent de cause non neurologique (diagnostic différentiel)","contenu":"<table >\n        <thead><tr><th>Cause</th><th>Arguments cliniques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Impotence fonctionnelle</strong></span></td>\n            <td>\n              <strong>Ostéo-articulaire :</strong> <span class=\"kw-etio\">fracture</span> ; <span class=\"kw-etio\">entorse</span> ; <span class=\"kw-etio\">arthrite</span> ; <span class=\"kw-etio\">rupture de coiffe</span> — <span class=\"kw-clinique\"><strong>douleur</strong></span> souvent au 1<sup>er</sup> plan<br>\n              <strong>Vasculaire périphérique :</strong> <span class=\"kw-etio\">occlusion artérielle aiguë</span> — <span class=\"kw-clinique\">douleur</span> quasi-constante\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Trouble somatoforme</strong></span></td>\n            <td>\n              <strong>Territoire :</strong> moteur ou sensitif <span class=\"kw-clinique\">aberrant</span>, <span class=\"kw-clinique\">non anatomique</span><br>\n              <strong>Examen :</strong> <span class=\"kw-clinique\">discordance</span> de l'examen clinique ; <span class=\"kw-clinique\">plaintes changeantes</span><br>\n              <strong>Contexte :</strong> hystérique (conversion) ; simulation ; syndrome dépressif\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Causes ORL / ophtalmologiques</strong></span></td>\n            <td>\n              <strong>Manifestations :</strong> troubles de l'<span class=\"kw-clinique\">élocution</span> ; troubles de l'<span class=\"kw-clinique\">équilibre</span> ; troubles de la <span class=\"kw-clinique\">vision</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"91-3","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les arguments en faveur d'un déficit récent d'origine somatomorphe","contenu":"<ul>\n        <li><span class=\"kw-clinique\">Territoire</span> <span class=\"kw-clinique\">moteur</span> ou <span class=\"kw-clinique\">sensitif</span> <span class=\"kw-clinique\"><strong>aberrant</strong></span>, <span class=\"kw-clinique\">non anatomique</span></li>\n        <li><span class=\"kw-clinique\"><strong>Discordance</strong></span> de l'<span class=\"kw-clinique\">examen clinique</span> (<span class=\"kw-clinique\">signes non reproductibles</span>, <span class=\"kw-clinique\">variables</span>)</li>\n        <li><span class=\"kw-clinique\">Plaintes changeantes</span> d'une consultation à l'autre</li>\n        <li>Contextes évocateurs : <span class=\"kw-etio\">hystérique (conversion)</span> ; <span class=\"kw-etio\">simulation</span> ; <span class=\"kw-etio\">syndrome dépressif</span></li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> <span class=\"kw-alerte\">Diagnostic d'élimination</span> — toujours après <span class=\"kw-imagerie\">imagerie</span> et <span class=\"kw-bio\">bilan neurologique</span> normaux. Ne jamais conclure à l'<span class=\"kw-etio\">origine somatomorphe</span> sans avoir écarté une <span class=\"kw-etio\">cause organique</span>.\n      </div>","frequence":1},{"id":"91-4","rang":"A","rubrique":"Diagnostic positif","titre":"Distinguer un déficit neurologique récent d'origine périphérique ou centrale","contenu":"<table >\n        <thead><tr><th>Atteinte</th><th>Arguments en faveur</th><th>Paraclinique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>SNC</strong></span></td>\n            <td>\n              <strong>Moteur :</strong> <span class=\"kw-clinique\">atteinte d'un hémicorps</span><br>\n              <strong>Pyramidal :</strong> <span class=\"kw-clinique\">ROT vifs</span> ; <span class=\"kw-clinique\">clonus de cheville</span> ; <span class=\"kw-clinique\">signe de Babinski</span><br>\n              <strong>Sensitif :</strong> <span class=\"kw-clinique\">niveau sensitif thoracique</span> ou abdominal franc<br>\n              <strong>Cortical :</strong> <span class=\"kw-clinique\">aphasie</span> ; hémianopsie latérale homonyme (HLH) ; troubles gnosiques<br>\n              <strong>Associés :</strong> troubles de la vigilance ; <span class=\"kw-etio\">crise d'épilepsie</span> ; atteinte des paires crâniennes avec atteinte des voies longues\n            </td>\n            <td>\n              <strong>Cérébral :</strong> <span class=\"kw-imagerie\">IRM cérébrale</span> (ou <span class=\"kw-imagerie\">TDM</span> à défaut)<br>\n              <strong>Vasculaire :</strong> <span class=\"kw-imagerie\">Angio-IRM</span> ou <span class=\"kw-imagerie\">Angio-TDM</span> cervico-encéphalique si suspicion d'<span class=\"kw-etio\">AVC</span><br>\n              <strong><span class=\"kw-def\">Épilepsie</span> :</strong> <span class=\"kw-bio\">EEG</span> si suspicion<br>\n              <strong>Médullaire :</strong> <span class=\"kw-imagerie\">IRM cervico-dorso-lombaire</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>SNP</strong></span></td>\n            <td>\n              <strong>Topographie :</strong> radiculaire ou tronculaire<br>\n              <strong>Amyotrophie :</strong> <span class=\"kw-clinique\">fasciculations</span> ; <span class=\"kw-clinique\">amyotrophie</span><br>\n              <strong>ROT :</strong> diminution ou abolition<br>\n              <strong>Distribution :</strong> atteinte distale des membres inférieurs sans troubles vésico-sphinctériens\n            </td>\n            <td>\n              <strong>Queue de cheval :</strong> <span class=\"kw-imagerie\">IRM lombaire</span><br>\n              <strong>Nerf / muscle :</strong> <span class=\"kw-bio\">EMG</span><br>\n              <strong>Inflammation :</strong> PL (polyradiculonévrite, <span class=\"kw-etio\">infectieux</span>, <span class=\"kw-etio\">inflammatoire</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Plaque motrice / Muscle</strong></span></td>\n            <td>\n              <strong>Moteur pur :</strong> pas de trouble sensitif, ni vésicosphinctérien<br>\n              <strong>Distribution :</strong> déficit à prédominance proximale<br>\n              <strong>ROT :</strong> normaux<br>\n              <strong><span class=\"kw-def\">IDM</span> :</strong> disparition de la réponse idio-musculaire\n            </td>\n            <td>\n              <strong>Électromyogramme :</strong> <span class=\"kw-bio\">EMG</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 92 — <span class=\"kw-clinique\">Déficit moteur</span>-sensitif membres</em></p>","frequence":1},{"id":"91-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique syndromique et topographique devant un déficit neurologique récent","contenu":"<p style=\"margin: 0 0 10px; font-size: 13px;\"><strong>Trois étapes séquentielles :</strong></p>\n      <ol style=\"margin: 0 0 14px; padding-left: 20px; font-size: 13px; line-height: 1.65;\">\n        <li><strong>Étape 1.</strong> <span class=\"kw-def\">Caractériser le déficit</span> : <span class=\"kw-clinique\">moteur</span> ; <span class=\"kw-clinique\">sensitif</span> ; <span class=\"kw-clinique\">sensoriel</span> ; <span class=\"kw-clinique\">cognitif</span></li>\n        <li><strong>Étape 2.</strong> <span class=\"kw-def\">Diagnostic syndromique et topographique</span> (central / périphérique / <span class=\"kw-clinique\">plaque</span> motrice / muscle)</li>\n        <li><strong>Étape 3.</strong> <span class=\"kw-def\">Identifier le mécanisme et la cause sous-jacente</span> — orienté par le mode d'installation</li>\n      </ol>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 252\" role=\"img\" aria-label=\"Frise temporelle du mode d'installation d'un déficit neurologique récent, orientant le mécanisme. De gauche à droite sur l'axe du temps : installation brutale en secondes à minutes, à évoquer un mécanisme vasculaire, c'est-à-dire un AVC jusqu'à preuve du contraire, urgence absolue. Puis installation aiguë ou subaiguë en heures à jours, orientant vers un mécanisme inflammatoire, infectieux ou toxique. Puis installation rapidement progressive en quelques semaines, orientant vers un processus expansif comme une tumeur, un abcès ou un hématome sous-dural. Enfin, une évolution en tâche d'huile, c'est-à-dire une aggravation progressive, fait évoquer un processus expansif.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"20\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\">Mode d'installation → mécanisme évoqué</text>\n          <text class=\"tx-muted\" x=\"20\" y=\"38\" font-size=\"10.5\">Axe du temps · plus c'est rapide, plus l'<span class=\"kw-alerte\">urgence</span> vasculaire prime</text>\n\n          <rect class=\"fb-red\" x=\"14\" y=\"50\" width=\"128\" height=\"74\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"78\" y=\"67\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Brutal</text>\n          <text class=\"tx-red\" x=\"78\" y=\"82\" text-anchor=\"middle\" font-size=\"10\">secondes – minutes</text>\n          <text class=\"tx-red\" x=\"78\" y=\"98\" text-anchor=\"middle\" font-size=\"9\">d'emblée maximal → <span class=\"kw-alerte\">AVC</span></text>\n\n          <rect class=\"fb-amber\" x=\"152\" y=\"50\" width=\"120\" height=\"74\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"212\" y=\"67\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Aigu / Subaigu</text>\n          <text class=\"tx-amber\" x=\"212\" y=\"82\" text-anchor=\"middle\" font-size=\"10\">heures – jours</text>\n          <text class=\"tx-amber\" x=\"212\" y=\"98\" text-anchor=\"middle\" font-size=\"9.5\">inflam. / infect.<tspan x=\"212\" dy=\"11\">/ <span class=\"kw-etio\">toxique</span></tspan></text>\n\n          <rect class=\"fb-amber\" x=\"282\" y=\"50\" width=\"120\" height=\"74\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"342\" y=\"64\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Rapidement<tspan x=\"342\" dy=\"13\">progressif</tspan></text>\n          <text class=\"tx-amber\" x=\"342\" y=\"92\" text-anchor=\"middle\" font-size=\"10\">quelques semaines</text>\n          <text class=\"tx-amber\" x=\"342\" y=\"108\" text-anchor=\"middle\" font-size=\"9.5\">processus expansif</text>\n\n          <rect class=\"fb-grey\" x=\"412\" y=\"50\" width=\"134\" height=\"74\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"479\" y=\"65\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Tâche d'huile</text>\n          <text class=\"tx-grey\" x=\"479\" y=\"80\" text-anchor=\"middle\" font-size=\"10\">aggravation<tspan x=\"479\" dy=\"12\">progressive</tspan></text>\n          <text class=\"tx-grey\" x=\"479\" y=\"108\" text-anchor=\"middle\" font-size=\"9.5\">→ processus expansif</text>\n\n          <line class=\"ln\" x1=\"14\" y1=\"138\" x2=\"540\" y2=\"138\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"552,138 540,132 540,144\"/>\n          <line class=\"ln\" x1=\"78\" y1=\"124\" x2=\"78\" y2=\"138\" stroke-width=\"1.5\"/>\n          <line class=\"ln\" x1=\"212\" y1=\"124\" x2=\"212\" y2=\"138\" stroke-width=\"1.5\"/>\n          <line class=\"ln\" x1=\"342\" y1=\"124\" x2=\"342\" y2=\"138\" stroke-width=\"1.5\"/>\n          <line class=\"ln\" x1=\"479\" y1=\"124\" x2=\"479\" y2=\"138\" stroke-width=\"1.5\"/>\n          <text class=\"tx-muted\" x=\"528\" y=\"132\" text-anchor=\"end\" font-size=\"10\" font-style=\"italic\">temps</text>\n\n          <text class=\"tx-red\" x=\"78\" y=\"156\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"600\">URGENCE</text>\n          <text class=\"tx-muted\" x=\"212\" y=\"156\" text-anchor=\"middle\" font-size=\"9.5\">bilan ciblé</text>\n          <text class=\"tx-muted\" x=\"342\" y=\"156\" text-anchor=\"middle\" font-size=\"9.5\"><span class=\"kw-imagerie\">IRM cérébrale</span></text>\n          <text class=\"tx-muted\" x=\"479\" y=\"156\" text-anchor=\"middle\" font-size=\"9.5\"><span class=\"kw-imagerie\">IRM cérébrale</span></text>\n\n          <rect class=\"fb-grey\" x=\"14\" y=\"176\" width=\"532\" height=\"62\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"26\" y=\"196\" font-size=\"10.5\" font-weight=\"600\">Cas particuliers (hors axe vitesse)</text>\n          <text class=\"tx-grey\" x=\"26\" y=\"214\" font-size=\"10\">Transitoire : examen clinique normal, interrogatoire ++ — origine majoritairement centrale</text>\n          <text class=\"tx-grey\" x=\"26\" y=\"230\" font-size=\"10\">Permanent : l'examen clinique permet de poser le diagnostic syndromique</text>\n        </svg>\n      </figure>\n      <table >\n        <thead><tr><th>Mode d'installation</th><th>Mécanismes évoqués</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-chiffre\"><strong>Brutal</strong></span><br><small>(secondes – minutes)</small></td>\n            <td>\n              <strong>D'emblée maximal :</strong> vasculaire surtout — <span class=\"kw-alerte\">AVC jusqu'à preuve du contraire</span><br>\n              <strong>Quelques dizaines de secondes :</strong> mécanisme épileptique (marche épileptique)<br>\n              <strong>Quelques dizaines de minutes :</strong> mécanisme migraineux (marche migraineuse)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-chiffre\"><strong>Aigu / Subaigu</strong></span><br><small>(heures – jours)</small></td>\n            <td>\n              <strong>Mécanismes :</strong> <span class=\"kw-etio\">inflammatoire</span> ; <span class=\"kw-etio\">infectieux</span> ; <span class=\"kw-etio\">toxique</span><br>\n              <strong>Vasculaire lent :</strong> thrombophlébite cérébrale ; thrombose artérielle in situ\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-chiffre\"><strong>Rapidement progressif</strong></span><br><small>(quelques semaines)</small></td>\n            <td>\n              <strong>Expansif :</strong> tumeur maligne ; <span class=\"kw-clinique\">abcès</span> ; hématome sous-dural<br>\n              <strong>Autres :</strong> <span class=\"kw-etio\">infectieux</span> ; métabolique\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-chiffre\"><strong>Transitoire</strong></span></td>\n            <td>Examen clinique <span class=\"kw-clinique\">normal</span> — interrogatoire ++ — origine majoritairement centrale</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-chiffre\"><strong>Permanent</strong></span></td>\n            <td>L'examen clinique permet de poser le diagnostic syndromique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-chiffre\"><strong>En tâche d'huile</strong></span></td>\n            <td><span class=\"kw-clinique\">Évolution</span> vers une <span class=\"kw-alerte\">aggravation progressive</span> → évoquer un <span class=\"kw-etio\">processus expansif</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Tout <span class=\"kw-alerte\"><strong>déficit brutal d'emblée maximal</strong></span> doit faire suspecter un <span class=\"kw-etio\"><strong>AVC</strong></span> jusqu'à preuve du contraire — imagerie cérébrale en urgence.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 92 — <span class=\"kw-clinique\">Déficit moteur</span>-sensitif membres</em></p>","frequence":3},{"id":"91-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens d'imagerie devant un déficit neurologique récent","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>IRM cérébrale</strong></span></td>\n            <td>Examen de référence — suspicion d'atteinte <span class=\"kw-def\">supramédullaire</span> (cérébrale ou médullaire haute)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>TDM cérébrale</strong></span></td>\n            <td>À défaut de l'<span class=\"kw-imagerie\">IRM</span>, ou en <span class=\"kw-alerte\">urgence</span> — réalisée <span class=\"kw-chiffre\">sans injection</span> en <span class=\"kw-chiffre\">1<sup>re</sup> intention</span> (<span class=\"kw-etio\">traumatisme</span>, suspicion d'<span class=\"kw-alerte\">hémorragie</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>Angio-IRM</strong></span> / <span class=\"kw-imagerie\">Angio-TDM</span> <span class=\"kw-def\">cervico-encéphalique</span></td>\n            <td>Suspicion d'<span class=\"kw-etio\">infarctus cérébral</span> (<span class=\"kw-etio\">occlusion artérielle</span>) — recherche de <span class=\"kw-imagerie\">sténose</span> ou occlusion</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>IRM médullaire</strong></span></td>\n            <td><span class=\"kw-def\">Syndrome médullaire</span> ou <span class=\"kw-def\">syndrome de la queue de cheval</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-etio\">AVC</span> · 341 — Hémorragie méningée</em></p>","frequence":1},{"id":"91-7","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales causes des déficits neurologiques récents centraux","contenu":"<table >\n        <thead><tr><th>Atteinte</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Encéphalique</strong></span></td>\n            <td>\n              <strong>Vasculaire :</strong> <span class=\"kw-etio\">infarctus cérébral</span> ; <span class=\"kw-etio\">hémorragie intraparenchymateuse</span> ; <span class=\"kw-etio\">thrombose veineuse cérébrale</span> ; <span class=\"kw-etio\">hémorragie méningée</span><br>\n              <strong>Traumatique :</strong> <span class=\"kw-etio\">hématome extradural (HED)</span> ; <span class=\"kw-etio\">hématome sous-dural (HSD)</span> ; contusion cérébrale<br>\n              <strong><span class=\"kw-etio\">Tumoral</span> :</strong> <span class=\"kw-etio\">tumeur gliale</span> ; <span class=\"kw-etio\">métastase cérébrale</span> ; <span class=\"kw-etio\">lymphome cérébral</span><br>\n              <strong><span class=\"kw-etio\">Infectieux</span> :</strong> <span class=\"kw-etio\">méningite</span> ; <span class=\"kw-etio\">méningo-encéphalite</span> ; <span class=\"kw-etio\">abcès cérébral</span> ; empyème<br>\n              <strong>Hématome sous-dural spontané :</strong> <span class=\"kw-alerte\">à évoquer</span><br>\n              <strong><span class=\"kw-etio\">Inflammatoire</span> :</strong> <span class=\"kw-etio\">poussée de SEP</span> ; <span class=\"kw-etio\">maladie de Behçet</span> ; <span class=\"kw-etio\">sarcoïdose</span><br>\n              <strong>Carentiel :</strong> <span class=\"kw-etio\">encéphalopathie de Gayet-Wernicke</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Médullaire</strong></span></td>\n            <td>\n              <strong>Compressif :</strong> <span class=\"kw-etio\">traumatique</span> ; <span class=\"kw-etio\">néoplasique</span> ; spondylodiscite / épidurite infectieuse ; <span class=\"kw-etio\">hernie discale</span> ; <span class=\"kw-etio\">hématome épidural</span><br>\n              <strong>Vasculaire :</strong> <span class=\"kw-etio\">infarctus médullaire</span> (<span class=\"kw-alerte\">dissection aortique</span>++)<br>\n              <strong><span class=\"kw-etio\">Inflammatoire</span> :</strong> myélite inflammatoire et infectieuse<br>\n              <strong>Carentiel :</strong> myélopathie carentielle\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-etio\">AVC</span> · 341 — Hémorragie méningée · 104 — SEP</em></p>","frequence":1},{"id":"91-8","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales causes des déficits neurologiques récents périphériques","contenu":"<table >\n        <thead><tr><th>Atteinte du SNP</th><th>Étiologies principales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Syndrome de la queue de cheval</strong></span></td>\n            <td><span class=\"kw-etio\">Hernie discale lombaire</span> ; <span class=\"kw-etio\">métastase</span> ; <span class=\"kw-etio\">épidurite</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Sciatique paralysante</strong></span></td>\n            <td>Atteinte uniradiculaire compressive — <span class=\"kw-alerte\">urgence chirurgicale</span> si déficit sévère</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Syndrome de Guillain-Barré</strong></span></td>\n            <td><span class=\"kw-etio\">Polyradiculonévrite aiguë inflammatoire</span> ; <span class=\"kw-etio\">méningoradiculites</span> infectieuses ou néoplasiques</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Plexopathie</strong></span></td>\n            <td>Traumatique ; <span class=\"kw-etio\">néoplasique</span> ; <span class=\"kw-etio\">syndrome de Parsonage-Turner</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Neuropathie multifocale</strong></span></td>\n            <td><span class=\"kw-etio\">Vasculaire</span> (<span class=\"kw-def\">vascularite</span>) ; <span class=\"kw-etio\">diabète</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Neuropathie unifocale</strong></span></td>\n            <td><span class=\"kw-etio\">Compression traumatique</span> ; posturale ; <span class=\"kw-etio\">ischémique</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 97 — Polyradiculonévrite aigue <span class=\"kw-etio\">inflammatoire</span> · 98 — Myasthénie</em></p>","frequence":0},{"id":"91-9","rang":"A","rubrique":"Diagnostic positif","titre":"Reconnaître un déficit récent par atteinte de la jonction neuromusculaire ou du muscle","contenu":"<p style=\"margin: 0 0 8px; font-size: 13px;\"><strong><span class=\"kw-def\">Critères cliniques</span> :</strong></p>\n      <ul style=\"margin: 0 0 12px; padding-left: 20px; font-size: 13px; line-height: 1.65;\">\n        <li><span class=\"kw-clinique\"><strong>Atteinte motrice pure</strong></span> — pas de trouble sensitif, ni vésicosphinctérien</li>\n        <li><span class=\"kw-clinique\">Déficit</span> à <span class=\"kw-clinique\"><strong>prédominance proximale</strong></span></li>\n        <li><span class=\"kw-clinique\"><strong>Réflexes ostéotendineux normaux</strong></span></li>\n        <li><span class=\"kw-clinique\"><strong>Disparition de la réponse idio-musculaire</strong></span></li>\n      </ul>\n      <table >\n        <thead><tr><th>Cause</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Jonction neuromusculaire</strong></span></td>\n            <td><span class=\"kw-etio\">Myasthénie</span> ; autres <span class=\"kw-etio\">syndromes myasthéniques</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Myosite</strong></span></td>\n            <td><span class=\"kw-etio\">Inflammatoire</span> ; <span class=\"kw-etio\">infectieuse</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Myopathie</strong></span></td>\n            <td><span class=\"kw-etio\">Toxique</span> ; métabolique (<span class=\"kw-etio\">dyskaliémie</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Rhabdomyolyse</strong></span></td>\n            <td><span class=\"kw-clinique\">Nécrose</span> musculaire aiguë — <span class=\"kw-bio\">CPK</span> <span class=\"kw-chiffre\">élevées</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p style=\"margin: 6px 0 0; font-size: 12.5px; color: var(--ink-muted)\"><strong>Paraclinique :</strong> <span class=\"kw-bio\">EMG</span> si suspicion d'atteinte de la <span class=\"kw-def\">JNM</span> ou du <span class=\"kw-def\">muscle</span></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 98 — Myasthénie</em></p>","frequence":0},{"id":"91-10","rang":"A","rubrique":"Examens complémentaires","titre":"Hiérarchiser les examens complémentaires non radiologiques devant un déficit neurologique récent","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Indication</th><th>Priorité</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Glycémie capillaire</strong></span></td>\n            <td>Devant <span class=\"kw-alerte\"><strong>tout déficit neurologique</strong></span> — l'<span class=\"kw-etio\">hypoglycémie</span> peut mimer n'importe quel signe focal</td>\n            <td><span class=\"kw-alerte\"><strong>Priorité absolue</strong></span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>EEG</strong></span></td>\n            <td>Suspicion de <span class=\"kw-etio\">crise d'épilepsie</span> (déficit transitoire ou permanent)</td>\n            <td>1<sup>re</sup> intention si contexte épileptique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>EMG</strong></span></td>\n            <td>Suspicion d'atteinte du <span class=\"kw-def\">SNP</span>, de la <span class=\"kw-def\">jonction neuromusculaire</span> ou du <span class=\"kw-def\">muscle</span></td>\n            <td>1<sup>re</sup> intention si contexte périphérique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Ponction lombaire (PL)</strong></span></td>\n            <td>Suspicion de <span class=\"kw-etio\">polyradiculonévrite</span> ; processus <span class=\"kw-etio\">infectieux</span> ou <span class=\"kw-etio\">inflammatoire</span></td>\n            <td>Après imagerie</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Bilan biologique</strong></span></td>\n            <td>Contexte <span class=\"kw-etio\">infectieux</span> : <span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">CRP</span> ; <span class=\"kw-bio\">PCT</span> ; <span class=\"kw-bio\">hémocultures</span></td>\n            <td>Selon contexte</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> La <span class=\"kw-bio\"><strong>glycémie capillaire</strong></span> doit être contrôlée <span class=\"kw-alerte\"><strong>devant tout déficit neurologique</strong></span> — une <span class=\"kw-etio\">hypoglycémie</span> peut donner des signes neurologiques focaux trompeurs.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 105 — Epilepsie</em></p>","frequence":0},{"id":"91-11","rang":"A","rubrique":"Identifier une urgence","titre":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","contenu":"<div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Signes de gravité</span>.</strong> <span class=\"kw-alerte\"><strong>Troubles de la vigilance</strong></span> ; <span class=\"kw-alerte\">troubles de la déglutition</span> ; <span class=\"kw-alerte\">atteinte respiratoire</span> ; <span class=\"kw-alerte\">atteinte hémodynamique</span> — nécessitent une prise en charge immédiate.\n      </div>\n      <table >\n        <thead><tr><th>Contexte</th><th><span class=\"kw-alerte\">Urgence</span> / Geste clé</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Traumatique</strong></td>\n            <td>\n              <strong>Imagerie :</strong> <span class=\"kw-imagerie\">TDM cérébrale sans injection</span> en <span class=\"kw-alerte\">urgence</span> — recherche <span class=\"kw-etio\">HED (hématome extra-dural)</span> ou <span class=\"kw-etio\">HSDA (hématome sous-dural aigu)</span><br>\n              <strong>Transfert :</strong> neurochirurgie si hématome → évacuation en urgence\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Infectieux</span></strong></td>\n            <td>\n              <strong>Causes :</strong> <span class=\"kw-etio\">méningo-encéphalite</span> ; <span class=\"kw-etio\">abcès cérébral</span><br>\n              <strong>Bilan :</strong> <span class=\"kw-bio\">sérologie</span> <span class=\"kw-etio\">VIH</span> ; <span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">CRP</span> ; <span class=\"kw-bio\">PCT</span> ; <span class=\"kw-bio\">hémocultures</span> ; <span class=\"kw-imagerie\">radiographie thoracique</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Métabolique</strong></td>\n            <td>\n              <strong>Hypoglycémie :</strong> <span class=\"kw-bio\">glycémie capillaire</span> — corriger en <span class=\"kw-alerte\">urgence</span><br>\n              <strong>Carentiel :</strong> <span class=\"kw-etio\">encéphalopathie de Gayet-Wernicke</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Périphérique extensif</strong></td>\n            <td>\n              <strong>Crise myasthénique :</strong> <span class=\"kw-bio\">EMG</span> + dosage <span class=\"kw-bio\">AC anti-RACh / anti-MuSK</span><br>\n              <strong>Guillain-Barré :</strong> <span class=\"kw-bio\">EMG</span> + PL (dissociation albumino-cytologique)<br>\n              <strong>Syndrome médullaire aigu / queue de cheval :</strong> <span class=\"kw-imagerie\">IRM médullaire en urgence</span> — si compression : transfert <span class=\"kw-ttt\">chirurgie</span> ; si myélite : <span class=\"kw-imagerie\">IRM cérébrale</span> + PL pour préciser la nature<br>\n              <strong>AVM :</strong> ne pas méconnaître <span class=\"kw-etio\"><strong>dissection aortique</strong></span> (cause d'<span class=\"kw-clinique\">infarctus</span> médullaire)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres urgences</strong></td>\n            <td>\n              <strong><span class=\"kw-etio\">AVC</span> :</strong> <span class=\"kw-etio\">ischémique</span> ; <span class=\"kw-etio\">hémorragie intraparenchymateuse</span> ; <span class=\"kw-etio\">thrombose veineuse cérébrale</span><br>\n              <strong><span class=\"kw-def\">État de mal épileptique</span> :</strong> <span class=\"kw-alerte\">urgence</span> thérapeutique — <span class=\"kw-bio\">EEG</span> + antiépileptiques IV\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-etio\">AVC</span> · 341 — Hémorragie méningée · 97 — Polyradiculonévrite aigue <span class=\"kw-etio\">inflammatoire</span> · 98 — Myasthénie · 105 — Epilepsie</em></p>","frequence":1},{"id":"91-12","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales causes de déficit neurologique récent transitoire","contenu":"<table >\n        <thead>\n          <tr>\n            <th></th>\n            <th><span class=\"kw-etio\">AIT</span></th>\n            <th><span class=\"kw-etio\">Crise d'épilepsie</span></th>\n            <th><span class=\"kw-etio\">Aura migraineuse</span></th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td><span class=\"kw-clinique\">&gt; 50 ans</span> ; <span class=\"kw-clinique\">facteurs de risque vasculaires</span></td>\n            <td>Variable ; ATCD d'<span class=\"kw-etio\">épilepsie</span> ou d'épisodes identiques</td>\n            <td><span class=\"kw-clinique\">&lt; 50 ans</span> ; ATCD de <span class=\"kw-etio\">migraine</span></td>\n          </tr>\n          <tr>\n            <td><strong>Installation</strong></td>\n            <td><span class=\"kw-clinique\">Brutal, d'emblée maximal</span></td>\n            <td><span class=\"kw-clinique\">Marche épileptique</span> de proche en proche en <span class=\"kw-chiffre\">quelques dizaines de secondes</span></td>\n            <td><span class=\"kw-clinique\">Marche migraineuse</span> avec extension sur <span class=\"kw-chiffre\">quelques dizaines de minutes</span></td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes</strong></td>\n            <td><span class=\"kw-clinique\"><strong>Négatifs</strong></span> : amputation du champ visuel ; perte de la sensibilité</td>\n            <td><span class=\"kw-clinique\"><strong>Positifs</strong></span> : <span class=\"kw-clinique\">paresthésies</span> ; illusions ; hallucinations visuelles</td>\n            <td><span class=\"kw-clinique\"><strong>Positifs</strong></span> : phénomènes visuels lumineux (<span class=\"kw-clinique\">scotome scintillant</span>) ; colorés — surtout visuels et sensitifs</td>\n          </tr>\n          <tr>\n            <td><strong>Signes associés</strong></td>\n            <td>Souffle vasculaire ; cardiopathie</td>\n            <td><span class=\"kw-clinique\">Clonies</span> dans les crises motrices ; <span class=\"kw-alerte\">rupture</span> de contact ; amnésie de l'épisode (crises partielles complexes)</td>\n            <td><span class=\"kw-clinique\">Céphalées</span> migraineuses : hémicranies ; photo-sono-phobie ; signes digestifs</td>\n          </tr>\n          <tr>\n            <td><strong>Résolution</strong></td>\n            <td>Rapide</td>\n            <td>Rapide</td>\n            <td>Progressive — durée du déficit <span class=\"kw-chiffre\">&lt; 1 h</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p style=\"margin: 12px 0 6px; font-size: 13px;\"><strong>Autres causes de déficit transitoire :</strong></p>\n      <table >\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Hypoglycémie</strong></span></td>\n            <td>Peut donner des <span class=\"kw-clinique\">signes neurologiques focaux</span> — contexte évocateur (diabétique traité) ; <span class=\"kw-bio\"><strong>glycémie capillaire à contrôler devant tout déficit neurologique</strong></span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Lésions cérébrales</strong></span></td>\n            <td><span class=\"kw-etio\">Hématome sous-dural</span> ; <span class=\"kw-etio\">tumeur cérébrale</span> ; <span class=\"kw-etio\">malformation vasculaire</span> → peuvent causer des déficits transitoires, souvent par <span class=\"kw-etio\">crise d'épilepsie surajoutée</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Compression nerveuse</strong></span></td>\n            <td>Atteinte tronculaire par compression posturale ou externe — en cas de récidive, chercher une <span class=\"kw-def\">neuropathie héréditaire avec hypersensibilité à la pression</span> (duplication du gène <span class=\"kw-def\"><strong>PMP22</strong></span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> <span class=\"kw-bio\"><strong>Glycémie capillaire</strong></span> à contrôler devant <span class=\"kw-alerte\"><strong>tout déficit neurologique</strong></span> — une <span class=\"kw-etio\">hypoglycémie</span> peut mimer n'importe quel signe focal transitoire.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-etio\">AVC</span> · 99 — <span class=\"kw-def\">Migraine</span> - névralgie trijumeau - algie face · 105 — Epilepsie</em></p>","frequence":0}],"astuces":[{"type":"info","titre":"Astuces & pièges et stratégie","contenu":"<p>Couches « Astuces de PU &amp; Pièges » et « Stratégie &amp; CAT » : à compléter après revue clinique.</p>"}],"strategie":{"urgence":"<p><strong>Réflexe systématique</strong></p><ul><li><span class=\"kw-bio\">glycémie capillaire</span> devant <span class=\"kw-alerte\">tout déficit neurologique</span></li><li>l'<span class=\"kw-etio\">hypoglycémie</span> mime n'importe quel signe focal</li></ul><p><strong>Brutal, d'emblée maximal</strong></p><p><span class=\"kw-imagerie\">imagerie cérébrale</span> + <span class=\"kw-imagerie\">angio cervico-encéphalique</span> en <span class=\"kw-alerte\">urgence</span></p><ul><li><span class=\"kw-etio\">AVC</span> jusqu'à preuve du contraire</li></ul><p><strong>Déficit post-traumatique</strong></p><p><span class=\"kw-imagerie\">TDM cérébrale sans injection</span> immédiate (<span class=\"kw-etio\">HED</span> / <span class=\"kw-etio\">HSD aigu</span>)</p><p><strong>Syndrome médullaire aigu / queue de cheval</strong></p><p><span class=\"kw-imagerie\">IRM médullaire</span> en <span class=\"kw-alerte\">urgence</span> (compression = urgence chirurgicale)</p>","hospit":"<p><strong>Ambulatoire :</strong> non en phase aiguë d'un déficit récent inexpliqué.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> <span class=\"kw-etio\">AVC</span> → <span class=\"kw-def\">UNV</span> ; <span class=\"kw-etio\">HED</span>/<span class=\"kw-etio\">HSD</span> ou <span class=\"kw-etio\">compression médullaire</span> → transfert <span class=\"kw-def\">neurochirurgie</span>.<br><strong><span class=\"kw-alerte\">Réanimation</span> :</strong> si <span class=\"kw-alerte\">trouble de la vigilance</span>, <span class=\"kw-alerte\">trouble de la déglutition</span>, <span class=\"kw-alerte\">atteinte respiratoire</span> ou <span class=\"kw-alerte\">atteinte hémodynamique</span> ; <span class=\"kw-etio\">paralysie extensive</span> (<span class=\"kw-etio\">Guillain-Barré</span>, <span class=\"kw-etio\">crise myasthénique</span>).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Trouble de la vigilance</span></li><li><span class=\"kw-alerte\">Trouble de la déglutition</span></li><li><span class=\"kw-alerte\">Atteinte respiratoire</span> — paralysie extensive (<span class=\"kw-etio\">Guillain-Barré</span>, <span class=\"kw-etio\">myasthénie</span>)</li><li><span class=\"kw-alerte\">Atteinte hémodynamique</span></li><li><span class=\"kw-alerte\">Déficit dans les suites d'un traumatisme crânien</span> (<span class=\"kw-etio\">HED</span> / <span class=\"kw-etio\">HSD</span>)</li><li>Aggravation <span class=\"kw-alerte\">« en tâche d'huile »</span> → <span class=\"kw-etio\">processus expansif</span></li><li>Ne pas méconnaître une <span class=\"kw-alerte\">dissection aortique</span> (cause d'<span class=\"kw-etio\">infarctus médullaire</span>)</li></ul>","principes":"<p><span class=\"kw-def\">Démarche en 3 temps</span> : caractériser le déficit → <span class=\"kw-def\">diagnostic syndromique et topographique</span> → identifier le <span class=\"kw-etio\">mécanisme</span> et la cause (orienté par le mode d'installation).</p><ul><li><span class=\"kw-bio\">Glycémie capillaire</span> en 1er — corriger toute <span class=\"kw-etio\">hypoglycémie</span> sans délai</li><li><span class=\"kw-imagerie\">Imagerie</span> selon la topographie : <span class=\"kw-imagerie\">IRM</span>/<span class=\"kw-imagerie\">TDM cérébrale</span> (+ <span class=\"kw-imagerie\">angio</span> si <span class=\"kw-etio\">AVC</span>) ; <span class=\"kw-imagerie\">IRM médullaire</span> si syndrome médullaire</li><li>Examens non radiologiques ciblés : <span class=\"kw-bio\">EEG</span> (épilepsie) ; <span class=\"kw-bio\">EMG</span> + <span class=\"kw-bio\">AC anti-RACh/anti-MuSK</span> (jonction/muscle) ; <span class=\"kw-bio\">PL</span> (<span class=\"kw-etio\">inflammatoire</span>/<span class=\"kw-etio\">infectieux</span>)</li><li><span class=\"kw-ttt\">Traitement étiologique</span> spécifique selon la cause (cf. items dédiés)</li></ul>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/deficit-neurologique-recent","label":"Collège CEN — Déficit neurologique récent"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Déficit neurologique récent (< <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> mois</span>) confirmé — Réflexe initial : <span class=\"kw-bio\">glycémie</span> capillaire","detail":"<h4>Démarche diagnostique devant un déficit neurologique récent — <span class=\"kw-bio\">Glycémie</span> → cause neurologique ? → gravité → mode d'installation</h4>","branches":[{"to":"t-hypo","label":"Glycémie basse","color":"amber"},{"to":"q-neuro","label":"Glycémie normale","color":"blue"}]},{"id":"t-hypo","kind":"terminal","label":"Hypoglycémie","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-bio\">Glycémie capillaire</span> contrôlée en <span class=\"kw-alerte\">urgence</span></li><li>Resucrage immédiat (<span class=\"kw-ttt\">resucrage oral</span> ou <span class=\"kw-ttt\">G30 % IV</span>)</li></ul><h4>Piège</h4><ul><li>Contexte évocateur (<span class=\"kw-etio\">diabétique traité</span>) — régression du déficit après correction</li></ul>"},{"id":"q-neuro","kind":"decision","label":"Déficit réellement neurologique ? — Éliminer une cause non neurologique","branches":[{"to":"t-nonneuro","label":"Non (douleur, territoire non anatomique, ORL/ophtalmo)","color":"blue"},{"to":"q-gravite","label":"Oui","color":"amber"}]},{"id":"t-nonneuro","kind":"terminal","label":"Cause non neurologique","color":"blue","detail":"<h4>Orientations</h4><ul><li><span class=\"kw-etio\">Impotence fonctionnelle</span> ostéo-articulaire ou vasculaire — <span class=\"kw-clinique\">douleur</span> au 1er plan</li><li><span class=\"kw-etio\">Trouble somatoforme</span> : territoire <span class=\"kw-clinique\">non anatomique</span>, <span class=\"kw-clinique\">discordance</span> de l'examen, plaintes changeantes</li><li><span class=\"kw-etio\">Cause ORL / ophtalmologique</span> : troubles de l'élocution, de l'équilibre, de la vision</li></ul><h4>Piège</h4><ul><li>Origine somatomorphe = <span class=\"kw-alerte\">diagnostic d'élimination</span>, jamais avant <span class=\"kw-imagerie\">imagerie</span> et bilan neurologique normaux</li></ul>"},{"id":"q-gravite","kind":"decision","label":"Signes de gravité ? — Vigilance · déglutition · respiration · hémodynamique","branches":[{"to":"t-urgence","label":"Oui","color":"red"},{"to":"q-installation","label":"Non","color":"amber"}]},{"id":"t-urgence","kind":"terminal","label":"Urgence vitale","color":"red","detail":"<h4>Conduite</h4><ul><li>Mise en condition + <span class=\"kw-alerte\">surveillance rapprochée</span></li><li><span class=\"kw-imagerie\">Imagerie cérébrale</span> immédiate en parallèle</li><li>Recherche étiologique sans retarder la prise en charge</li></ul><h4><span class=\"kw-alerte\">Red flags</span></h4><ul><li><span class=\"kw-alerte\">Trouble de la vigilance</span> ; <span class=\"kw-alerte\">trouble de la déglutition</span> ; <span class=\"kw-alerte\">atteinte respiratoire</span> ; <span class=\"kw-alerte\">atteinte hémodynamique</span></li></ul>"},{"id":"q-installation","kind":"decision","label":"Mode d'installation ? — Oriente le mécanisme et la cause","branches":[{"to":"t-avc","label":"Brutal, d'emblée maximal","color":"red"},{"to":"t-epilepsie","label":"Dizaines de secondes (marche)","color":"amber"},{"to":"t-migraine","label":"Dizaines de minutes (phénomènes positifs)","color":"green"},{"to":"t-inflam","label":"Heures – jours (aigu/subaigu)","color":"amber"},{"to":"t-expansif","label":"Semaines / « en tâche d'huile »","color":"amber"},{"to":"t-transitoire","label":"Transitoire, examen normal","color":"blue"}]},{"id":"t-avc","kind":"terminal","label":"AVC jusqu'à preuve du contraire","color":"red","detail":"<h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">IRM</span> (ou <span class=\"kw-imagerie\">TDM</span> à défaut) + <span class=\"kw-imagerie\">angio-IRM/TDM cervico-encéphalique</span> en <span class=\"kw-alerte\">urgence</span></li></ul><h4>Mécanismes</h4><ul><li><span class=\"kw-etio\">Infarctus cérébral</span> ; <span class=\"kw-etio\">hémorragie intraparenchymateuse</span> ; <span class=\"kw-etio\">thrombose veineuse cérébrale</span></li></ul><h4>Renvoi</h4><ul><li>Item 340 (<span class=\"kw-alerte\">AVC</span>) · Item 341 (Hémorragie méningée)</li></ul>"},{"id":"t-epilepsie","kind":"terminal","label":"Mécanisme épileptique","color":"amber","detail":"<h4>Installation</h4><ul><li><span class=\"kw-clinique\">Marche épileptique</span> de proche en proche en <span class=\"kw-chiffre\">quelques dizaines de secondes</span> ; signes <span class=\"kw-clinique\">positifs</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">EEG</span></li></ul><h4>Renvoi</h4><ul><li>Item 105 (Épilepsie)</li></ul>"},{"id":"t-migraine","kind":"terminal","label":"Aura migraineuse","color":"green","detail":"<h4>Installation</h4><ul><li><span class=\"kw-clinique\">Marche migraineuse</span> sur <span class=\"kw-chiffre\">quelques dizaines de minutes</span> ; phénomènes <span class=\"kw-clinique\">positifs</span> visuels (<span class=\"kw-clinique\">scotome scintillant</span>) puis <span class=\"kw-clinique\">céphalée</span></li></ul><h4><span class=\"kw-def\">Terrain</span></h4><ul><li><span class=\"kw-clinique\">&lt; 50 ans</span>, ATCD de <span class=\"kw-etio\">migraine</span> ; durée du déficit <span class=\"kw-chiffre\">&lt; 1 h</span></li></ul><h4>Renvoi</h4><ul><li>Item 99 (Migraine - névralgie trijumeau - algie face)</li></ul>"},{"id":"t-inflam","kind":"terminal","label":"Inflammatoire / infectieux / toxique","color":"amber","detail":"<h4>Mécanismes</h4><ul><li><span class=\"kw-etio\">Inflammatoire</span> (<span class=\"kw-etio\">SEP</span>, myélite) ; <span class=\"kw-etio\">infectieux</span> (<span class=\"kw-etio\">méningo-encéphalite</span>, <span class=\"kw-etio\">abcès</span>) ; <span class=\"kw-etio\">toxique</span> ; certaines causes vasculaires lentes (<span class=\"kw-etio\">thrombophlébite cérébrale</span>)</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM</span> + <span class=\"kw-bio\">PL</span> ; bilan <span class=\"kw-etio\">infectieux</span> (<span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">hémocultures</span>)</li></ul><h4>Renvoi</h4><ul><li>Item 104 (SEP)</li></ul>"},{"id":"t-expansif","kind":"terminal","label":"Processus expansif","color":"amber","detail":"<h4>Évocation</h4><ul><li>Aggravation progressive sur <span class=\"kw-chiffre\">quelques semaines</span> / <span class=\"kw-clinique\">« en tâche d'huile »</span></li></ul><h4>Causes</h4><ul><li><span class=\"kw-etio\">Tumeur maligne</span> ; <span class=\"kw-etio\">abcès cérébral</span> ; <span class=\"kw-etio\">hématome sous-dural</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM cérébrale</span></li></ul>"},{"id":"t-transitoire","kind":"terminal","label":"Déficit transitoire — à trier","color":"blue","detail":"<h4>Démarche</h4><ul><li>Examen clinique <span class=\"kw-clinique\">normal</span>, interrogatoire ++ ; origine majoritairement <span class=\"kw-def\">centrale</span></li></ul><h4>Trois causes</h4><ul><li><span class=\"kw-etio\">AIT</span> : <span class=\"kw-clinique\">&gt; 50 ans</span>, FdR vasculaires, signes <span class=\"kw-clinique\">négatifs</span>, résolution rapide</li><li><span class=\"kw-etio\">Crise d'épilepsie</span> : marche en secondes, signes <span class=\"kw-clinique\">positifs</span></li><li><span class=\"kw-etio\">Aura migraineuse</span> : marche en minutes, phénomènes visuels</li></ul><h4>Renvoi</h4><ul><li>Item 340 (<span class=\"kw-alerte\">AVC</span>) · Item 105 (Épilepsie) · Item 99 (Migraine)</li></ul>"}]},"cards":[{"i":"3fcd41b0b5da","n":91,"o":"91-1","u":"Définition","t":"Définir la notion de déficit neurologique focal vs trouble cérébral diffus","q":"Quelle est la définition d'un déficit neurologique focal ?","a":"<p>C'est une <strong>dysfonction localisée</strong> à une région précise du système nerveux, traduisant une <strong>lésion ou irritation focale</strong>.</p>"},{"i":"40d08a3b05f5","n":91,"o":"91-1","u":"Définition","t":"Définir la notion de déficit neurologique focal vs trouble cérébral diffus","q":"Qu'est-ce qui caractérise une souffrance cérébrale diffuse ?","a":"<p>Une souffrance cérébrale diffuse se caractérise par une <strong>atteinte globale du cerveau</strong>, se manifestant typiquement par une <strong>perte de connaissance</strong>, un <strong>coma</strong> ou un <strong>syndrome confusionnel</strong>. Elle doit être distinguée d'un déficit focal.</p>"},{"i":"4948d705cd46","n":91,"o":"91-1","u":"Définition","t":"Définir la notion de déficit neurologique focal vs trouble cérébral diffus","q":"Quelle est la définition d'un déficit neurologique ?","a":"<p>C'est une <strong>dysfonction</strong>, temporaire ou lésionnelle, d'une région du <strong>système nerveux</strong>.</p>"},{"i":"f98660e2a329","n":91,"o":"91-1","u":"Définition","t":"Définir la notion de déficit neurologique focal vs trouble cérébral diffus","q":"Comment définit-on un déficit neurologique récent ?","a":"<p>Un déficit neurologique est qualifié de récent s'il est apparu depuis <strong>moins d'un mois</strong>.</p>"},{"i":"0fbf9512f7f4","n":91,"o":"91-10","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires non radiologiques devant un déficit neurologique récent","q":"Dans quel contexte et quels examens sont inclus dans le bilan biologique devant un déficit neurologique récent ?","a":"<p>Un bilan biologique est indiqué dans un <strong>contexte infectieux</strong>. Il inclut une <strong>NFS</strong> (numération formule sanguine), la <strong>CRP</strong> (protéine C-réactive), la <strong>PCT</strong> (procalcitonine) et des <strong>hémocultures</strong>, selon le contexte clinique.</p>"},{"i":"397c3f702dd9","n":91,"o":"91-10","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires non radiologiques devant un déficit neurologique récent","q":"Quelle est l'indication et la priorité de la glycémie capillaire devant un déficit neurologique récent ?","a":"<p>La glycémie capillaire est indiquée devant <strong>tout déficit neurologique</strong>. C'est un examen de <strong>priorité absolue</strong> car une hypoglycémie peut mimer n'importe quel signe focal et donner des signes neurologiques trompeurs.</p>"},{"i":"6d1ea9a0cfcd","n":91,"o":"91-10","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires non radiologiques devant un déficit neurologique récent","q":"Quelles sont les principales indications d'une ponction lombaire (PL) devant un déficit neurologique récent, et quand doit-elle être réalisée ?","a":"<p>La ponction lombaire est indiquée en cas de <strong>suspicion de polyradiculonévrite</strong> ou de <strong>processus infectieux ou inflammatoire</strong>. Elle doit être réalisée <strong>après imagerie</strong> cérébrale.</p>"},{"i":"ace268320c8b","n":91,"o":"91-10","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires non radiologiques devant un déficit neurologique récent","q":"Quand l'EMG est-il indiqué devant un déficit neurologique récent et quelle est sa priorité ?","a":"<p>L'EMG (électromyogramme) est indiqué en cas de <strong>suspicion d'atteinte du système nerveux périphérique (SNP)</strong>, de la <strong>jonction neuromusculaire</strong> ou du <strong>muscle</strong>. Il est réalisé en <strong>1<sup>re</sup> intention</strong> si le contexte suggère une origine périphérique au déficit.</p>"},{"i":"f7a43ec3799d","n":91,"o":"91-10","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires non radiologiques devant un déficit neurologique récent","q":"Dans quel contexte et avec quelle priorité l'EEG est-il indiqué devant un déficit neurologique récent ?","a":"<p>L'EEG (électroencéphalogramme) est indiqué en cas de <strong>suspicion de crise d'épilepsie</strong> (qu'elle entraîne un déficit transitoire ou permanent). Il s'agit d'un examen de <strong>1<sup>re</sup> intention</strong> si le contexte est épileptique.</p>"},{"i":"45da925dee58","n":91,"o":"91-11","u":"Identifier une urgence","t":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","q":"Quels sont les signes de gravité à rechercher en présence d'un déficit neurologique récent, justifiant une prise en charge immédiate ?","a":"<p>Les signes de gravité justifiant une prise en charge immédiate en présence d'un déficit neurologique récent sont :</p><ul><li>Des <strong>troubles de la vigilance</strong>.</li><li>Des <strong>troubles de la déglutition</strong>.</li><li>Une <strong>atteinte respiratoire</strong>.</li><li>Une <strong>atteinte hémodynamique</strong>.</li></ul>"},{"i":"7a91e55d6be2","n":91,"o":"91-11","u":"Identifier une urgence","t":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","q":"Quelles sont les étiologies métaboliques urgentes à rechercher en cas de déficit neurologique ?","a":"<p>Les étiologies métaboliques urgentes à rechercher sont :</p><ul><li>L'<strong>hypoglycémie</strong>, confirmée par une glycémie capillaire et à corriger en urgence.</li><li>L'<strong>encéphalopathie de Gayet-Wernicke</strong>, cause carentielle.</li></ul>"},{"i":"7b639a093770","n":91,"o":"91-11","u":"Identifier une urgence","t":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","q":"Face à un déficit neurologique d'origine infectieuse, quelles sont les causes à évoquer et les bilans à réaliser ?","a":"<p>Les causes infectieuses à évoquer devant un déficit neurologique sont la <strong>méningo-encéphalite</strong> et l'<strong>abcès cérébral</strong>. Le bilan à réaliser inclut :</p><ul><li><strong>Sérologie VIH</strong>.</li><li><strong>NFS</strong>, <strong>CRP</strong>, <strong>PCT</strong>.</li><li><strong>Hémocultures</strong>.</li><li><strong>Radiographie thoracique</strong>.</li></ul>"},{"i":"ab77f117f559","n":91,"o":"91-11","u":"Identifier une urgence","t":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","q":"Comment prendre en charge un syndrome médullaire aigu ou de la queue de cheval ?","a":"<p>La prise en charge d'un syndrome médullaire aigu ou de la queue de cheval repose sur :</p><ul><li>Une <strong>IRM médullaire en urgence</strong>.</li><li>En cas de <strong>compression</strong>, un <strong>transfert chirurgical</strong> est indiqué.</li><li>En cas de <strong>myélite</strong>, une <strong>IRM cérébrale</strong> et une <strong>PL</strong> sont réalisées pour préciser sa nature.</li><li>Ne pas négliger la recherche d'une <strong>dissection aortique</strong>, cause possible d'infarctus médullaire.</li></ul>"},{"i":"b594e676ea12","n":91,"o":"91-11","u":"Identifier une urgence","t":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","q":"Quelles sont les autres urgences neurologiques non encore citées pouvant provoquer un déficit neurologique récent ?","a":"<p>Les autres urgences neurologiques à considérer devant un déficit neurologique récent sont :</p><ul><li>Les <strong>accidents vasculaires cérébraux (AVC)</strong> : ischémique, hémorragie intraparenchymateuse, thrombose veineuse cérébrale.</li><li>L'<strong>état de mal épileptique</strong>, qui est une <strong>urgence thérapeutique</strong> nécessitant <strong>EEG</strong> et <strong>antiépileptiques IV</strong>.</li></ul>"},{"i":"b5eb45be14e0","n":91,"o":"91-11","u":"Identifier une urgence","t":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","q":"En cas de déficit neurologique traumatique, quel est l'examen d'imagerie clé et que recherche-t-il ?","a":"<p>En cas de déficit neurologique traumatique, l'examen d'imagerie clé est une <strong>TDM cérébrale sans injection en urgence</strong>. Elle permet de rechercher un <strong>hématome extra-dural (HED)</strong> ou un <strong>hématome sous-dural aigu (HSDA)</strong>.</p>"},{"i":"c8579fc491f7","n":91,"o":"91-11","u":"Identifier une urgence","t":"Face à un déficit neurologique récent, identifier une situation d'urgence et connaître les principes de prise en charge","q":"Devant un déficit neurologique récent périphérique extensif, quelles urgences diagnostiques doivent être recherchées ?","a":"<p>Devant un déficit neurologique récent périphérique extensif, il faut rechercher en urgence :</p><ul><li>Une <strong>crise myasthénique</strong> (diagnostiquée par <strong>EMG</strong> et dosage des <strong>AC anti-RACh / anti-MuSK</strong>).</li><li>Un <strong>Guillain-Barré</strong> (diagnostiqué par <strong>EMG</strong> et <strong>PL</strong> montrant une <strong>dissociation albumino-cytologique</strong>).</li></ul>"},{"i":"133abb0ed986","n":91,"o":"91-12","u":"Etiologies","t":"Connaître les principales causes de déficit neurologique récent transitoire","q":"Quelles sont les autres causes de déficit neurologique transitoire, en dehors de l'AIT, de la crise d'épilepsie et de l'aura migraineuse ?","a":"<ul><li>L'<strong>hypoglycémie</strong> : elle peut mimer n'importe quel signe focal transitoire, surtout chez un patient <strong>diabétique traité</strong>. Une glycémie capillaire est à contrôler devant tout déficit neurologique.</li><li>Les <strong>lésions cérébrales</strong> : un hématome sous-dural, une tumeur cérébrale ou une malformation vasculaire peuvent entraîner des déficits transitoires, souvent par <strong>crise d'épilepsie surajoutée</strong>.</li><li>La <strong>compression nerveuse</strong> : une atteinte tronculaire par compression posturale ou externe. En cas de récidive, il faut rechercher une <strong>neuropathie héréditaire avec hypersensibilité à la pression</strong> (duplication du gène PMP22).</li></ul>"},{"i":"5b4da5b1ebf2","n":91,"o":"91-12","u":"Etiologies","t":"Connaître les principales causes de déficit neurologique récent transitoire","q":"Quelle est la définition d'un Accident Ischémique Transitoire (AIT) et ses caractéristiques cliniques principales ?","a":"<p>Un AIT est un <strong>déficit neurologique transitoire d'origine vasculaire</strong>. Il survient brutalement, d'emblée maximal, et se caractérise par des symptômes neurologiques <strong>négatifs</strong> (ex: amputation du champ visuel, perte de sensibilité) qui se résolvent rapidement, en <strong>moins d'une heure</strong>.</p>"},{"i":"784b608d6846","n":91,"o":"91-12","u":"Etiologies","t":"Connaître les principales causes de déficit neurologique récent transitoire","q":"Comment différencier cliniquement une crise d'épilepsie d'un Accident Ischémique Transitoire (AIT) ou d'une aura migraineuse sur la base de l'installation des symptômes ?","a":"<ul><li>Pour une <strong>crise d'épilepsie</strong>, l'installation se fait généralement de <strong>proche en proche</strong> en quelques dizaines de secondes (marche épileptique).</li><li>Pour une <strong>aura migraineuse</strong>, l'extension est progressive sur quelques dizaines de minutes (marche migraineuse).</li><li>L'<strong>AIT</strong> s'installe <strong>brutalement</strong>, d'emblée maximal.</li></ul>"},{"i":"bfec30eb4f6e","n":91,"o":"91-12","u":"Etiologies","t":"Connaître les principales causes de déficit neurologique récent transitoire","q":"Quels sont les signes associés et le terrain évocateur d'une aura migraineuse comparé à une crise d'épilepsie ou un AIT ?","a":"<ul><li>Pour l'<strong>aura migraineuse</strong> : les symptômes sont souvent <strong>positifs</strong> (phénomènes visuels lumineux comme un scotome scintillant, colorés), surtout visuels et sensitifs. Elle est associée à des <strong>céphalées migraineuses</strong> (hémicrânies, photo-sono-phobie, signes digestifs) et survient souvent chez des patients avec des <strong>antécédents de migraine</strong>.</li><li>Pour la <strong>crise d'épilepsie</strong> : signes associés sont des <strong>clonies</strong> dans les crises motrices, une <strong>rupture de contact</strong> et une <strong>amnésie de l'épisode</strong> (crises partielles complexes). Le terrain est celui d'<strong>antécédents d'épilepsie</strong> ou d'épisodes identiques avant 50 ans.</li><li>Pour l'<strong>AIT</strong> : il y a souvent un <strong>contexte vasculaire</strong> (patient > 50 ans, facteurs de risque vasculaires, souffle vasculaire, cardiopathie).</li></ul>"},{"i":"20fc4dfdb7d2","n":91,"o":"91-2","u":"Diagnostic positif","t":"Reconnaître un déficit récent de cause non neurologique (diagnostic différentiel)","q":"Comment différencier cliniquement une occlusion artérielle aiguë d'un déficit neurologique récent chez un patient présentant un membre déficitaire ?","a":"<p>Devant une occlusion artérielle aiguë, la <strong>douleur est quasi-constante</strong> et souvent intense, ce qui la distingue d'un déficit neurologique pur. D'autres signes vasculaires (pâleur, froidur, abolition des pouls) sont également présents.</p>"},{"i":"46d64ce8c594","n":91,"o":"91-2","u":"Diagnostic positif","t":"Reconnaître un déficit récent de cause non neurologique (diagnostic différentiel)","q":"Quelles sont les principales caractéristiques cliniques qui orientent vers une impotence fonctionnelle d'origine ostéo-articulaire plutôt qu'un déficit neurologique récent ?","a":"<p>L'impotence fonctionnelle d'origine ostéo-articulaire est souvent caractérisée par une <strong>douleur au premier plan</strong>, contrairement à un déficit neurologique pur. Les causes peuvent inclure une <strong>fracture</strong>, une <strong>entorse</strong>, une <strong>arthrite</strong> ou une <strong>rupture de coiffe</strong>.</p>"},{"i":"4974d5d5d9c0","n":91,"o":"91-2","u":"Diagnostic positif","t":"Reconnaître un déficit récent de cause non neurologique (diagnostic différentiel)","q":"Quels arguments cliniques doivent faire évoquer un trouble somatoforme devant un déficit neurologique potentiellement non organique ?","a":"<p>Un trouble somatoforme peut être suspecté si le déficit moteur ou sensitif est <strong>aberrant</strong> et <strong>non anatomique</strong>, ne respectant pas les territoires neurologiques connus. L'examen clinique peut montrer une <strong>discordance</strong> entre les plaintes et les signes objectifs, avec des <strong>plaintes changeantes</strong>. Le contexte peut inclure un <strong>contexte hystérique (conversion)</strong>, une <strong>simulation</strong> ou un <strong>syndrome dépressif</strong> sous-jacent.</p>"},{"i":"f41e13e4db8f","n":91,"o":"91-2","u":"Diagnostic positif","t":"Reconnaître un déficit récent de cause non neurologique (diagnostic différentiel)","q":"Quels sont les déficits non neurologiques pouvant mimer des troubles neurologiques mais étant d'origine ORL ou ophtalmologique ?","a":"<p>Des causes ORL ou ophtalmologiques peuvent se manifester par des <strong>troubles de l'élocution</strong> (dysphonie, dysarthrie non neurologique), des <strong>troubles de l'équilibre</strong> (vertiges périphériques) ou des <strong>troubles de la vision</strong> (par exemple, baisse d'acuité visuelle aiguë d'origine oculaire pure), qui peuvent à tort être interprétés comme des déficits neurologiques centraux ou périphériques.</p>"},{"i":"019e04e2fdc3","n":91,"o":"91-4","u":"Diagnostic positif","t":"Distinguer un déficit neurologique récent d'origine périphérique ou centrale","q":"Quels sont les arguments cliniques majeurs suggérant un déficit neurologique récent d'origine centrale au niveau du Système Nerveux Central (SNC) ?","a":"<p>Les arguments cliniques majeurs pour un déficit neurologique récent d'origine centrale au niveau du SNC incluent :</p><ul><li>Une <strong>atteinte d'un hémicorps</strong> (hémiplégie ou hémiparésie).</li><li>Des signes pyramidaux : <strong>ROT vifs</strong>, <strong>clonus de cheville</strong>, <strong>signe de Babinski</strong>.</li><li>Un <strong>niveau sensitif thoracique ou abdominal franc</strong>.</li><li>Des signes associés : <strong>aphasie</strong>, <strong>hémianopsie latérale homonyme (HLH)</strong>, troubles gnosiques.</li><li>La présence de <strong>troubles de la vigilance</strong>, de <strong>crises d'épilepsie</strong> ou d'une atteinte des paires crâniennes avec atteinte des voies longues.</li></ul>"},{"i":"070eed19847f","n":91,"o":"91-4","u":"Diagnostic positif","t":"Distinguer un déficit neurologique récent d'origine périphérique ou centrale","q":"Comment distinguer cliniquement un déficit neurologique d'origine centrale (pyramidale) d'une atteinte périphérique (système nerveux périphérique) ?","a":"<p>La distinction clinique peut être faite ainsi :</p><ul><li><strong>Origine centrale (pyramidale)</strong> : atteinte d'un hémicorps, <strong>ROT vifs</strong>, <strong>signe de Babinski</strong>, clonus de cheville, parfois aphasie ou HLH.</li><li><strong>Origine périphérique (SNP)</strong> : déficit radiculaire ou tronculaire, <strong>amyotrophie</strong> (avec fasciculations), <strong>ROT diminués ou abolis</strong>, distribution distale des membres inférieurs sans troubles vésico-sphinctériens (sauf si queue de cheval).</li></ul>"},{"i":"0726f1463b2f","n":91,"o":"91-4","u":"Diagnostic positif","t":"Distinguer un déficit neurologique récent d'origine périphérique ou centrale","q":"Quels sont les examens paracliniques de première intention pour explorer un déficit neurologique récent suspecté d'origine centrale ?","a":"<p>Pour explorer un déficit neurologique récent d'origine centrale, les examens paracliniques de première intention sont :</p><ul><li>Une <strong>IRM cérébrale</strong> (ou TDM cérébrale à défaut) en cas de suspicion d'atteinte cérébrale.</li><li>Une <strong>Angio-IRM</strong> ou <strong>Angio-TDM cervico-encéphalique</strong> en cas de forte suspicion d'accident vasculaire cérébral (AVC).</li><li>Une <strong>IRM cervico-dorso-lombaire</strong> en cas de suspicion de pathologie médullaire.</li><li>Un <strong>EEG</strong> en cas de suspicion d'épilepsie.</li></ul>"},{"i":"2fbb22b6e1be","n":91,"o":"91-4","u":"Diagnostic positif","t":"Distinguer un déficit neurologique récent d'origine périphérique ou centrale","q":"Quels sont les arguments cliniques orientant vers une atteinte du Système Nerveux Périphérique (SNP) dans le cadre d'un déficit neurologique récent ?","a":"<p>Les arguments cliniques orientant vers une atteinte du SNP sont :</p><ul><li>Une topographie <strong>radiculaire ou tronculaire</strong> du déficit.</li><li>La présence d'<strong>amyotrophie</strong> avec ou sans fasciculations.</li><li>Une <strong>diminution ou abolition des ROT</strong>.</li><li>Une distribution du déficit le plus souvent <strong>distale des membres inférieurs</strong>.</li><li>L'absence de troubles vésico-sphinctériens (sauf en cas d'atteinte de la <strong>queue de cheval</strong>).</li></ul>"},{"i":"6b7449bab610","n":91,"o":"91-4","u":"Diagnostic positif","t":"Distinguer un déficit neurologique récent d'origine périphérique ou centrale","q":"Quels sont les arguments cliniques spécifiques suggérant une atteinte de la plaque motrice ou du muscle lui-même (myopathie/myasthénie) face à un déficit moteur ?","a":"<p>Les arguments cliniques suggérant une atteinte de la plaque motrice ou du muscle sont :</p><ul><li>Un <strong>déficit moteur pur</strong>, sans trouble sensitif ni vésico-sphinctérien associé.</li><li>Un déficit à prédominance <strong>proximale</strong>.</li><li>Des <strong>ROT normaux</strong>.</li><li>Une <strong>disparition de la réponse idio-musculaire</strong> à l'IDM (recherche du réflexe idiomusculaire).</li></ul>"},{"i":"9ca8fb67caa4","n":91,"o":"91-4","u":"Diagnostic positif","t":"Distinguer un déficit neurologique récent d'origine périphérique ou centrale","q":"Quels examens paracliniques sont utiles pour confirmer un déficit neurologique récent d'origine périphérique ?","a":"<p>Pour confirmer un déficit neurologique récent d'origine périphérique, les examens utiles sont :</p><ul><li>L'<strong>électromyogramme (EMG)</strong> pour évaluer l'atteinte du nerf et/ou du muscle.</li><li>Une <strong>IRM lombaire</strong> en cas de suspicion d'atteinte de la queue de cheval.</li><li>Une <strong>ponction lombaire (PL)</strong> pour rechercher une inflammation (polyradiculonévrite, processus infectieux ou inflammatoire).</li></ul>"},{"i":"126015d10048","n":91,"o":"91-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit neurologique récent","q":"Quelle est l'attitude d'urgence devant un déficit neurologique brutal d'emblée maximal ?","a":"<p>Devant un déficit neurologique <strong>brutal d'emblée maximal</strong>, il faut suspecter un <strong>AVC</strong> jusqu'à preuve du contraire, ce qui impose la réalisation d'une <strong>imagerie cérébrale en urgence</strong> (IRM ou scanner selon la disponibilité).</p>"},{"i":"12ecc7c8869f","n":91,"o":"91-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit neurologique récent","q":"Quels sont les mécanismes à considérer devant un déficit neurologique d'installation aiguë ou subaiguë (heures à jours) ?","a":"<p>Devant un déficit neurologique d'installation <strong>aiguë ou subaiguë</strong> (heures à jours), les mécanismes à considérer sont :</p><ul><li><strong>Inflammatoire</strong>.</li><li><strong>Infectieux</strong>.</li><li><strong>Toxique</strong>.</li><li>Un mécanisme <strong>vasculaire lent</strong> (thrombophlébite cérébrale, thrombose artérielle in situ).</li></ul>"},{"i":"66173e25088d","n":91,"o":"91-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit neurologique récent","q":"Quelle est la signification d'une évolution en \"tâche d'huile\" ou rapidement progressive sur quelques semaines pour un déficit neurologique ?","a":"<p>Une évolution en \"tâche d'huile\" ou rapidement progressive sur quelques semaines, caractérisée par une <strong>aggravation progressive</strong> du déficit neurologique, doit faire évoquer un <strong>processus expansif</strong> tel qu'une tumeur maligne, un abcès, ou un hématome sous-dural. D'autres causes comme infectieuses ou métaboliques sont aussi possibles.</p>"},{"i":"a35a8570c208","n":91,"o":"91-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit neurologique récent","q":"Quelles sont les trois étapes séquentielles de la démarche diagnostique devant un déficit neurologique récent ?","a":"<p>La démarche diagnostique devant un déficit neurologique récent comprend trois étapes :</p><ul><li><strong>Étape 1 : Caractériser le déficit</strong> (moteur, sensitif, sensoriel, cognitif).</li><li><strong>Étape 2 : Poser le diagnostic syndromique et topographique</strong> (central, périphérique, plaque motrice, muscle).</li><li><strong>Étape 3 : Identifier le mécanisme et la cause sous-jacente</strong>, orienté par le mode d'installation.</li></ul>"},{"i":"aa9474f94a1d","n":91,"o":"91-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit neurologique récent","q":"Comment est orienté le diagnostic en cas de déficit neurologique transitoire, où l'examen clinique est normal au moment de la consultation ?","a":"<p>En cas de déficit neurologique <strong>transitoire</strong>, lorsque l'examen clinique est normal, le diagnostic est principalement orienté par un <strong>interrogatoire minutieux</strong> du patient. L'origine est <strong>majoritairement centrale</strong> dans ces cas.</p>"},{"i":"d8e0498e995d","n":91,"o":"91-5","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit neurologique récent","q":"Quel mécanisme doit être prioritairement évoqué devant un déficit neurologique d'installation brutale (secondes à minutes) et d'emblée maximal ?","a":"<p>Devant un déficit neurologique d'installation <strong>brutale</strong> (secondes à minutes) et <strong>d'emblée maximal</strong>, un mécanisme <strong>vasculaire</strong>, notamment un <strong>AVC</strong>, doit être évoqué en priorité jusqu'à preuve du contraire.</p>"},{"i":"0477a81c5b38","n":91,"o":"91-6","u":"Examens complémentaires","t":"Connaître les indications des examens d'imagerie devant un déficit neurologique récent","q":"Quand faut-il envisager une Angio-IRM ou une Angio-TDM cervico-encéphalique face à un déficit neurologique récent ?","a":"<p>Ces examens sont indiqués en cas de <strong>suspicion d'infarctus cérébral</strong> (occlusion artérielle) afin de rechercher une <strong>sténose ou une occlusion</strong>.</p>"},{"i":"58693bdcd8da","n":91,"o":"91-6","u":"Examens complémentaires","t":"Connaître les indications des examens d'imagerie devant un déficit neurologique récent","q":"Quand l'IRM médullaire est-elle préconisée devant un déficit neurologique récent ?","a":"<p>L'IRM médullaire est préconisée en cas de <strong>syndrome médullaire</strong> ou de <strong>syndrome de la queue de cheval</strong>.</p>"},{"i":"a3c655a36355","n":91,"o":"91-6","u":"Examens complémentaires","t":"Connaître les indications des examens d'imagerie devant un déficit neurologique récent","q":"Dans quelles situations spécifiques la TDM cérébrale est-elle indiquée en première intention ou en l'absence d'IRM lors d'un déficit neurologique récent ?","a":"<p>La TDM cérébrale est indiquée en l'absence d'IRM, ou en urgence, notamment en cas de <strong>traumatisme</strong> ou de suspicion d'<strong>hémorragie</strong>. Elle est réalisée <strong>sans injection</strong> en première intention.</p>"},{"i":"ef2c85162d2e","n":91,"o":"91-6","u":"Examens complémentaires","t":"Connaître les indications des examens d'imagerie devant un déficit neurologique récent","q":"Quelle est l'indication principale de l'IRM cérébrale devant un déficit neurologique récent, selon l'objectif EDN ?","a":"<p>L'IRM cérébrale est l'<strong>examen de référence</strong> en cas de suspicion d'atteinte <strong>supramédullaire</strong> (cérébrale ou médullaire haute) devant un déficit neurologique récent.</p>"},{"i":"140abec92df5","n":91,"o":"91-7","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents centraux","q":"Quelles sont les étiologies traumatiques à considérer en cas de déficit neurologique récent d'origine encéphalique ?","a":"Les étiologies traumatiques encéphaliques sont :<ul><li>L'<strong>hématome extradural</strong> (HED).</li><li>L'<strong>hématome sous-dural</strong> (HSD).</li><li>La <strong>contusion cérébrale</strong>.</li><li>L'<strong>hématome sous-dural spontané</strong> peut aussi être évoqué.</li></ul>"},{"i":"1b1828c4e7ae","n":91,"o":"91-7","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents centraux","q":"Quelles sont les causes vasculaires de déficit neurologique récent d'origine encéphalique ?","a":"Les causes vasculaires d'atteinte encéphalique comprennent :<ul><li>L'<strong>infarctus cérébral</strong>.</li><li>L'<strong>hémorragie intraparenchymateuse</strong>.</li><li>La <strong>thrombose veineuse cérébrale</strong>.</li><li>L'<strong>hémorragie méningée</strong>.</li></ul>"},{"i":"3ee53eda2755","n":91,"o":"91-7","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents centraux","q":"Quelles sont les principales causes compressives de déficit neurologique récent d'origine médullaire ?","a":"Les causes compressives médullaires sont :<ul><li>D'origine <strong>traumatique</strong>.</li><li>D'origine <strong>néoplasique</strong>.</li><li>La <strong>spondylodiscite ou épidurite infectieuse</strong>.</li><li>La <strong>hernie discale</strong>.</li><li>L'<strong>hématome épidural</strong>.</li></ul>"},{"i":"69b1f7e6e1a6","n":91,"o":"91-7","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents centraux","q":"Quelles sont les causes tumorales et infectieuses de déficit neurologique récent d'origine encéphalique ?","a":"Les causes tumorales sont :<ul><li>La <strong>tumeur gliale</strong>.</li><li>Les <strong>métastases cérébrales</strong>.</li><li>Le <strong>lymphome cérébral</strong>.</ul>Les causes infectieuses sont :<ul><li>La <strong>méningite</strong>.</li><li>La <strong>méningo-encéphalite</strong>.</li><li>L'<strong>abcès cérébral</strong>.</li><li>L'<strong>empyème</strong>.</li></ul>"},{"i":"7e8bdef74fc3","n":91,"o":"91-7","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents centraux","q":"Quelles sont les causes inflammatoires ou carentielles de déficit neurologique récent d'origine encéphalique ?","a":"Les causes inflammatoires encéphaliques incluent :<ul><li>La <strong>poussée de SEP</strong> (Sclérose en Plaques).</li><li>La <strong>maladie de Behçet</strong>.</li><li>La <strong>sarcoïdose</strong>.</ul>La principale cause carentielle est l'<strong>encéphalopathie de Gayet-Wernicke</strong>."},{"i":"c86b32ad8de5","n":91,"o":"91-7","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents centraux","q":"Quelles sont les causes vasculaires, inflammatoires ou carentielles de déficit neurologique récent d'origine médullaire ?","a":"Les causes médullaires sont :<ul><li><strong>Vasculaire</strong> : l'<strong>infarctus médullaire</strong>, notamment suite à une <strong>dissection aortique</strong>.</li><li><strong>Inflammatoire</strong> : la <strong>myélite inflammatoire et infectieuse</strong>.</li><li><strong>Carentielle</strong> : la <strong>myélopathie carentielle</strong>.</li></ul>"},{"i":"35126145f787","n":91,"o":"91-8","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents périphériques","q":"Quelles sont les étiologies des plexopathies, causes de déficits neurologiques périphériques ?","a":"<p>Les étiologies des plexopathies sont :</p><ul><li>Les causes <strong>traumatiques</strong>.</li><li>Les causes <strong>néoplasiques</strong>.</li><li>Le <strong>syndrome de Parsonage-Turner</strong>.</li></ul>"},{"i":"4c9ce50fde61","n":91,"o":"91-8","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents périphériques","q":"Quelles sont les principales causes de neuropathies multifocales, un type de déficit neurologique périphérique récent ?","a":"<p>Les principales causes de neuropathies multifocales sont :</p><ul><li>Les causes <strong>vasculaires</strong> (comme les <strong>vascularites</strong>).</li><li>Le <strong>diabète</strong>.</li></ul>"},{"i":"a1fe987890b7","n":91,"o":"91-8","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents périphériques","q":"Quelles sont les principales étiologies des neuropathies unifocales, causes de déficits neurologiques périphériques récents ?","a":"<p>Les principales étiologies des neuropathies unifocales sont :</p><ul><li>La <strong>compression traumatique</strong>.</li><li>La <strong>compression posturale</strong>.</li><li>L'<strong>ischémie</strong>.</li></ul>"},{"i":"cb32abc09e38","n":91,"o":"91-8","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents périphériques","q":"Quelle est la principale cause d'une sciatique paralysante, représentant un déficit neurologique périphérique récent ?","a":"<p>La principale cause d'une sciatique paralysante est une <strong>atteinte uniradiculaire compressive</strong>, qui peut nécessiter une <strong>urgence chirurgicale</strong> si le déficit est sévère.</p>"},{"i":"ce5bc966ba5d","n":91,"o":"91-8","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents périphériques","q":"Quelles sont les étiologies des polyradiculonévrites aiguës, causes de déficits neurologiques périphériques ?","a":"<p>Les étiologies des polyradiculonévrites aiguës incluent :</p><ul><li>Le <strong>syndrome de Guillain-Barré</strong> (polyradiculonévrite aiguë inflammatoire).</li><li>Les <strong>méningoradiculites infectieuses</strong>.</li><li>Les <strong>méningoradiculites néoplasiques</strong>.</li></ul>"},{"i":"e86f0bce9cc3","n":91,"o":"91-8","u":"Etiologies","t":"Connaître les principales causes des déficits neurologiques récents périphériques","q":"Quelles sont les causes possibles du syndrome de la queue de cheval, un déficit neurologique périphérique récent ?","a":"<p>Les principales causes du syndrome de la queue de cheval sont :</p><ul><li>La <strong>hernie discale lombaire</strong>.</li><li>Les <strong>métastases</strong>.</li><li>L'<strong>épidurite</strong>.</li></ul>"},{"i":"3340656f7651","n":91,"o":"91-9","u":"Diagnostic positif","t":"Reconnaître un déficit récent par atteinte de la jonction neuromusculaire ou du muscle","q":"Quels sont les trois principaux critères cliniques qui orientent vers une atteinte de la jonction neuromusculaire (JNM) ou du muscle lors d'un déficit neurologique récent ?","a":"<p>Les trois principaux critères cliniques sont :</p><ul><li>Une <strong>atteinte motrice pure</strong>, sans trouble sensitif ni vésicosphinctérien associé.</li><li>Un déficit à <strong>prédominance proximale</strong>.</li><li>Des <strong>réflexes ostéotendineux normaux</strong>.</li></ul>"},{"i":"3ecfe6189bbd","n":91,"o":"91-9","u":"Diagnostic positif","t":"Reconnaître un déficit récent par atteinte de la jonction neuromusculaire ou du muscle","q":"Comment le test de la réponse idiomusculaire peut-il orienter vers une atteinte des muscles, et quel est le signe recherché ?","a":"<p>La recherche de la réponse idiomusculaire peut orienter vers une atteinte musculaire. Le signe recherché est la <strong>disparition de la réponse idiomusculaire</strong>, qui correspond à la rétraction localisée d'un muscle après une percussion directe.</p>"},{"i":"595d35de2c1e","n":91,"o":"91-9","u":"Diagnostic positif","t":"Reconnaître un déficit récent par atteinte de la jonction neuromusculaire ou du muscle","q":"Quelles sont les causes à évoquer devant une atteinte de la jonction neuromusculaire ou du muscle, selon le contenu donné ?","a":"<p>Les principales causes à évoquer sont :</p><ul><li>Atteinte de la Jonction Neuromusculaire (JNM) : <strong>Myasthénie</strong> ou autres syndromes myasthéniques.</li><li>Atteinte musculaire de type <strong>Myosite</strong> : inflammatoire ou infectieuse.</li><li>Atteinte musculaire de type <strong>Myopathie</strong> : toxique ou métabolique (notamment les <strong>dyskaliémies</strong>).</li><li><strong>Rhabdomyolyse</strong> : nécrose musculaire aiguë, caractérisée par des <strong>CPK élevées</strong>.</li></ul>"},{"i":"c5f7b004f0e7","n":91,"o":"91-9","u":"Diagnostic positif","t":"Reconnaître un déficit récent par atteinte de la jonction neuromusculaire ou du muscle","q":"Quel examen paraclinique est indiqué en cas de suspicion clinique d'atteinte de la jonction neuromusculaire ou du muscle ?","a":"<p>En cas de suspicion clinique d'atteinte de la jonction neuromusculaire ou du muscle, l'examen paraclinique indiqué est l'<strong>électromyogramme (EMG)</strong>.</p>"}]};